//js:
const qy71v = {
    host: 'https://www.71v.net',
    d: [],
    d_: [],
    vodCard: function(href, titleText, picUrl, remarks) {
        var self = this;
        if (href && href.indexOf('http') !== 0 && href.indexOf('/') === 0) href = self.host + href;
        if (picUrl && picUrl.indexOf('http') !== 0 && picUrl.indexOf('/') === 0) picUrl = self.host + picUrl;
        var m = href.match(/\/voddetail\/(\d+)/);
        var vid = m ? m[1] : '';
        var title = (titleText || '').trim();
        if (!title) return null;
        return {
            title: title,
            img: picUrl || '',
            desc: remarks || '',
            col_type: 'movie_3',
            url: $('hiker://empty').rule(function(o) {
                putMyVar('vod_id', o.vod_id);
                putMyVar('vod_name', o.vod_name);
                $.require('qy71v').detail();
            }, { vod_id: vid, vod_name: title })
        };
    },
    pickCards: function(html) {
        var self = this;
        var out = [];
        var doc = null;
        try { doc = PDFocument(html); } catch (e) { doc = null; }
        if (!doc) return out;
        var selectors = [
            '.module-items .module-item',
            '.vodlist .vod-item',
            '.stui-vodlist__item',
            '.public-list-box .public-list-item',
            '.card'
        ];
        var items = null;
        for (var s = 0; s < selectors.length; s++) {
            try {
                var t = doc.querySelectorAll(selectors[s]);
                if (t && t.length >= 2) { items = t; break; }
            } catch (e) {}
        }
        if (!items || !items.length) {
            try { items = doc.querySelectorAll('a[href*="/voddetail/"]'); } catch (e) {}
        }
        if (!items) return out;
        var limit = items.length < 60 ? items.length : 60;
        for (var j = 0; j < limit; j++) {
            var it = items[j];
            try {
                var tag = '';
                try { if (it.tagName) tag = it.tagName(); } catch (e) {}
                var a = null;
                if (tag && tag.toUpperCase() === 'A') {
                    a = it;
                } else {
                    try { a = it.querySelector('a[href*="/voddetail/"]'); } catch (e2) {}
                    if (!a) { try { a = it.querySelector('a'); } catch (e3) {} }
                }
                if (!a) continue;
                var img = null;
                try { img = it.querySelector('img'); } catch (e4) {}
                if (!img && a && a.querySelector) { try { img = a.querySelector('img'); } catch (e5) {} }
                var ttext = '';
                try { ttext = a.text() || ''; } catch (e) {}
                var tn = null;
                try { tn = it.querySelector('h3, h4, .title, .vod_title, .module-item-title'); } catch (e) {}
                if (tn) { try { ttext = tn.text() || ttext; } catch (e) {} }
                ttext = (ttext || '').trim();
                var dn = null;
                try { dn = it.querySelector('.remarks, .subtitle, .vod_sub, .module-item-subtitle, .module-item-content'); } catch (e) {}
                var dtext = '';
                if (dn) { try { dtext = dn.text() || ''; } catch (e) {} }
                var href = '';
                try { href = a.attr ? a.attr('href') : ''; } catch (e) {}
                var imgAttr = '';
                if (img) {
                    try { imgAttr = img.attr ? (img.attr('data-src') || img.attr('data-original') || img.attr('src') || '') : ''; } catch (e) {}
                }
                var c = self.vodCard(href, ttext, imgAttr, dtext);
                if (c) out.push(c);
            } catch (e) {}
        }
        return out;
    },
    home: function() {
        var self = this, d = this.d, d_ = this.d_;
        var pg = MY_PAGE;
        if (pg == 1) {
            d_.push({
                title: '搜索',
                col_type: 'input',
                extra: {
                    onChange: $.toString(function(v) {
                        putMyVar('keyword', v);
                        $.require('qy71v').search();
                    })
                }
            });
            var cats = ['首页','电影','电视剧','综艺','动漫','短剧','体育','纪录片','游戏','音乐','预告片','公益'];
            var cids = ['home','1','2','3','4','63','17','60','21','20','11','23'];
            for (var i = 0; i < cats.length; i++) {
                (function(tn, tid) {
                    d_.push({
                        title: getMyVar('cat71', 'home') == tid ? '「' + tn + '」' : tn,
                        url: $('#noLoading#').lazyRule(function(id) {
                            putMyVar('cat71', id);
                            refreshPage(false);
                            return 'hiker://empty';
                        }, tid),
                        col_type: 'scroll_button'
                    });
                })(cats[i], cids[i]);
            }
            setPreResult(d_);
        }
        var cat = getMyVar('cat71', 'home');
        if (cat == 'home') {
            self.hotList(pg);
        } else {
            self.category(cat, pg);
        }
        setResult(d);
    },
    hotList: function(pg) {
        var self = this, d = this.d;
        var html = request(self.host + '/?pg=' + pg, {
            headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' }
        });
        var rs = self.pickCards(html);
        if (!rs.length) d.push({ title: '首页暂无匹配数据', col_type: 'text_center_1' });
        for (var i = 0; i < rs.length; i++) d.push(rs[i]);
    },
    category: function(tid, pg) {
        var self = this, d = this.d;
        var url = self.host + '/vodtype/' + tid + '-----------' + pg + '---.html';
        var html;
        try {
            html = request(url, {
                headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' }
            });
        } catch (e) {
            url = self.host + '/vodshow/' + tid + '-----------' + pg + '---.html';
            html = request(url, {
                headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' }
            });
        }
        var rs = self.pickCards(html);
        if (!rs.length) d.push({ title: '分类页无数据（可能被CF风控）', col_type: 'text_center_1' });
        for (var i = 0; i < rs.length; i++) d.push(rs[i]);
    },
    search: function() {
        var self = this, d = this.d;
        var kw = getMyVar('keyword', '');
        if (!kw) { setResult(d); return; }
        var pg = typeof MY_PAGE !== 'undefined' ? MY_PAGE : 1;
        var url = self.host + '/vodsearch/-------------' + pg + '---/?wd=' + encodeURIComponent(kw);
        var html = request(url, {
            headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' }
        });
        var rs = self.pickCards(html);
        if (!rs.length) d.push({ title: '没有找到 ' + kw + ' 相关的影片', col_type: 'text_center_1' });
        for (var i = 0; i < rs.length; i++) d.push(rs[i]);
        setResult(d);
    },
    detail: function() {
        var self = this, d = this.d;
        var vid = MY_PARAMS.vod_id || getMyVar('vod_id', '');
        var name = MY_PARAMS.vod_name || getMyVar('vod_name', '');
        var html = request(self.host + '/voddetail/' + vid + '/', {
            headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' }
        });
        var doc = null;
        try { doc = PDFocument(html); } catch (e) { doc = null; }
        var vTitle = name || '';
        if (doc) {
            try {
                var te = doc.querySelector('h1') || doc.querySelector('h2') || doc.querySelector('.vod_title, .module-info-title, .title');
                vTitle = te ? (te.text() || '').trim() || vTitle : vTitle;
            } catch (e) {}
        }
        setPageTitle(vTitle);
        var vPic = '';
        if (doc) {
            try {
                var ie = doc.querySelector('.vod-img img, .module-info-poster img, .stui-content__thumb img, img[src*="/upload/"]');
                if (ie) {
                    try { vPic = ie.attr('data-src') || ie.attr('data-original') || ie.attr('src') || ''; } catch (e2) {}
                    if (vPic && vPic.indexOf('http') !== 0 && vPic.indexOf('/') === 0) vPic = self.host + vPic;
                }
            } catch (e) {}
        }
        var info = '';
        if (doc) {
            try {
                var ie2 = doc.querySelector('.vod_content, .vod-data, .module-info-content, .stui-content__detail, .vod-info');
                info = ie2 ? (ie2.text() || '').replace(/\s+/g, ' ').trim() : '';
            } catch (e) {}
        }
        var intro = '';
        if (doc) {
            try {
                var ie3 = doc.querySelector('.vod_content_intro, .module-info-intro, .detail-content, .vod_content, .stui-content__detail .detail-sketch');
                intro = ie3 ? (ie3.text() || '').trim() : '';
            } catch (e) {}
        }
        d.push({
            title: vTitle,
            desc: info,
            img: vPic,
            url: vPic ? (vPic + '#.jpg#') : '',
            col_type: 'movie_1_vertical_pic_blur'
        });
        if (intro) {
            d.push({
                title: '<b><font color="#098AC1">∷剧情简介</font></b><br>' + intro,
                col_type: 'rich_text',
                extra: { id: 'desc', lineSpacing: 6, textSize: 15, lineVisible: true }
            });
        }
        var tabs = [], lists = [];
        if (doc) {
            try {
                var anchors = doc.querySelectorAll('a[href*="/play/"]');
                var groups = {};
                var order = [];
                var playRe = /\/play\/(\d+)-(\d+)-(\d+)/;
                if (anchors && anchors.length) {
                    for (var k = 0; k < anchors.length; k++) {
                        var a = anchors[k];
                        var href = '';
                        try { href = a.attr('href') || ''; } catch (e) {}
                        var mm = href.match(playRe);
                        if (!mm) continue;
                        var sid = mm[2];
                        var nid = mm[3];
                        var ttxt = '';
                        try { ttxt = (a.text() || '').trim(); } catch (e) {}
                        if (!ttxt) continue;
                        if (!groups[sid]) { groups[sid] = []; order.push(sid); }
                        groups[sid].push({ t: ttxt, nid: nid, vid: mm[1], sid: sid });
                    }
                }
                var lineNames = {};
                var defIdx = 1;
                try {
                    var lineNodes = doc.querySelectorAll('.ylsp-mobile-source-card, .ylsp-pc-source-card, a[href*="/play/"][href*="-1-1"], .module-player-handle-items [class*="source"], [class*="play-from"]');
                    if (lineNodes && lineNodes.length) {
                        for (var ln = 0; ln < lineNodes.length && ln < order.length; ln++) {
                            var tt = '';
                            try { tt = (lineNodes[ln].text() || '').replace(/\s+/g, '').trim(); } catch (e) {}
                            var pn = tt.replace(/\d{2,}/g, '').replace(/个视频/g, '') || ('线路' + (ln + 1));
                            lineNames[order[ln]] = pn || ('线路' + (ln + 1));
                        }
                    }
                } catch (e) {}
                for (var oi = 0; oi < order.length; oi++) {
                    var sk = order[oi];
                    var arr = groups[sk];
                    if (!arr || !arr.length) continue;
                    var lname = lineNames[sk] || ('线路' + (defIdx++));
                    tabs.push(lname + '(' + arr.length + ')');
                    var eps = [];
                    var seen = {};
                    for (var ai = 0; ai < arr.length; ai++) {
                        if (seen[arr[ai].nid]) continue;
                        seen[arr[ai].nid] = true;
                        eps.push(arr[ai].t + '$' + arr[ai].sid + '$' + arr[ai].nid + '$' + arr[ai].vid);
                    }
                    if (eps.length) lists.push(eps);
                }
            } catch (e) {}
        }
        if (lists.length) {
            d.push({ col_type: 'blank_block' });
            storage0.putMyVar('lists71', lists);
            var 排序 = getMyVar(MY_URL + '章节排序', '正序');
            d.push({
                title: 排序,
                url: $('#noLoading#').lazyRule(function() {
                    var ls = storage0.getMyVar('lists71');
                    var cur = getMyVar(MY_URL, '0');
                    var 新排序 = getMyVar(MY_URL + '章节排序', '正序') == '倒序' ? '正序': '倒序';
                    var 章节 = ls[cur] || [];
                    if (新排序 == '倒序') 章节 = 章节.slice().reverse();
                    var cp = [];
                    for (var i = 0; i < 章节.length; i++) {
                        var parts = 章节[i].split('$');
                        cp.push({
                            title: parts[0],
                            url: $.require('qy71v').playUrl(parts[1], parts[2], parts[3]),
                            col_type: 章节.length > 3 ? 'text_4' : 'text_2',
                            extra: { cls: MY_URL + '_选集', id: parts[1] + '$' + parts[2] + '$' + parts[3] }
                        });
                    }
                    deleteItemByCls(MY_URL + '_选集');
                    addItemBefore(MY_URL + 'footer', cp);
                    updateItem(MY_URL + '_排序', { title: 新排序 });
                    putMyVar(MY_URL + '章节排序', 新排序);
                    return 'hiker://empty';
                }),
                col_type: 'flex_button',
                extra: { id: MY_URL + '_排序' }
            });
            for (var ti = 0; ti < tabs.length; ti++) {
                (function(tname, tid) {
                    d.push({
                        title: getMyVar(MY_URL, '0') == String(tid) ? '「 ' + tname + '」' : tname,
                        url: $('#noLoading#').lazyRule(function(tabs, id) {
                            var ls = storage0.getMyVar('lists71');
                            var 排序 = getMyVar(MY_URL + '章节排序', '正序');
                            for (var x = 0; x < tabs.length; x++) {
                                updateItem(MY_URL + '_线路' + x, { title: id == x ? '「' + tabs[x] + '」' : tabs[x] });
                            }
                            putMyVar(MY_URL, String(id));
                            var 章节 = ls[getMyVar(MY_URL, '0')] || [];
                            if (排序 == '倒序') 章节 = 章节.slice().reverse();
                            var cp = [];
                            for (var i = 0; i < 章节.length; i++) {
                                var parts = 章节[i].split('$');
                                cp.push({
                                    title: parts[0],
                                    url: $.require('qy71v').playUrl(parts[1], parts[2], parts[3]),
                                    col_type: 章节.length > 3 ? 'text_4' : 'text_2',
                                    extra: { cls: MY_URL + '_选集', id: parts[1] + '$' + parts[2] + '$' + parts[3] }
                                });
                            }
                            deleteItemByCls(MY_URL + '_选集');
                            addItemBefore(MY_URL + 'footer', cp);
                            return 'hiker://empty';
                        }, tabs, tid),
                        col_type: 'flex_button',
                        extra: { id: MY_URL + '_线路' + tid }
                    });
                })(tabs[ti], ti);
            }
            var list = lists[getMyVar(MY_URL, '0')] || [];
            if (排序 == '倒序') list = list.slice().reverse();
            for (var i = 0; i < list.length; i++) {
                var parts = list[i].split('$');
                d.push({
                    title: parts[0],
                    url: $.require('qy71v').playUrl(parts[1], parts[2], parts[3]),
                    col_type: list.length > 3 ? 'text_4' : 'text_2',
                    extra: { cls: MY_URL + '_选集', id: parts[1] + '$' + parts[2] + '$' + parts[3] }
                });
            }
            d.push({ col_type: 'big_blank_block', extra: { id: MY_URL + 'footer' } });
        }
        setResult(d);
    },
    playUrl: function(sid, nid, vid) {
        if (sid === undefined || nid === undefined || vid === undefined) return 'hiker://empty';
        return $('').lazyRule(function(s, n, v) {
            return $.require('qy71v').play(s, n, v);
        }, sid, nid, vid);
    },
    play: function(sid, nid, vid) {
        var self = this;
        var url = self.host + '/play/' + vid + '-' + sid + '-' + nid + '/';
        var html = request(url, {
            headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' }
        });
        var real = '';
        var mm = html.match(/var\s+player_aaaa\s*=\s*(\{[\s\S]*?\})\s*;/);
        if (mm) {
            try {
                var obj = JSON.parse(mm[1]);
                var rawUrl = obj && obj.url;
                if (rawUrl) {
                    var enc = String(obj.encrypt || '0');
                    if (enc === '1') { try { rawUrl = unescape(rawUrl); } catch (e) {} }
                    else if (enc === '2') { try { if (typeof atob === 'function') rawUrl = unescape(atob(rawUrl)); } catch (e) {} }
                    real = rawUrl;
                }
            } catch (e) {}
        }
        if (!real) {
            var mm2 = html.match(/https?:\/\/[^"')\s]+\.(?:m3u8|mp4|flv)(?:\?[^"')\s]*)?/);
            if (mm2) real = mm2[0];
        }
        if (!real) {
            setError('播放地址为空（可能被CF风控或接口变了）');
            return 'hiker://empty';
        }
        return real;
    }
};
$.exports = qy71v;
